-- Upgrade only unchanged default process copy. Preserve custom drafts, SEO, galleries and field overrides.
UPDATE content_items SET draft_json=json_set(draft_json,'$.title',CASE WHEN coalesce(json_extract(draft_json,'$.title'),'')=json_extract('{"v":"How Your Custom Sign Project Works"}','$.v') THEN json_extract('{"v":"Your Idea. Made into a Sign."}','$.v') ELSE json_extract(draft_json,'$.title') END,'$.intro',CASE WHEN coalesce(json_extract(draft_json,'$.intro'),'')=json_extract('{"v":"Start with what you know. We’ll clarify the remaining details with you before confirming a quote and production specification."}','$.v') THEN json_extract('{"v":"A clear path from your first reference to an agreed specification, production and delivery. Start with the details you have."}','$.v') ELSE json_extract(draft_json,'$.intro') END,'$.body',json_extract('{"v":"## Share Your Brief\n\nA logo, a reference or a photo of the space is enough to begin the discussion.\n\nWe review the starting information and clarify the style, size, quantity and any open requirements with you.\n\nA saved enquiry and a clear starting point for your project.\n\n## Specification & Quote\n\nBring the artwork, construction and supplied scope together before the order moves forward.\n\nWe review the artwork, materials, lighting, fixing and delivery requirements, then prepare a project-based quote.\n\nReview the specification, price, inclusions and order terms. Approve the agreed requirements in writing before production.\n\n## Production & Checks\n\nThe approved details guide fabrication, finishing and the checks required for your sign.\n\nWe make your sign to the confirmed requirements and carry out the agreed appearance, construction and lighting checks where applicable.\n\nComplete the agreed order checks and confirm the packing and dispatch arrangements.\n\n## Delivery Preparation\n\nPlan the packing, shipment and local installation together, before dispatch.\n\nWe prepare the agreed protection and shipment arrangements, and confirm the supplied installation information.\n\nKnow the shipping scope, timing and import responsibilities. Resolve local fixing, electrical work and approvals with your installer."}','$.v'),'$.image',CASE WHEN coalesce(json_extract(draft_json,'$.image'),'')=json_extract('{"v":""}','$.v') THEN json_extract('{"v":"/assets/product-depth/metal-cut.webp"}','$.v') ELSE json_extract(draft_json,'$.image') END,'$.imageAlt',CASE WHEN coalesce(json_extract(draft_json,'$.imageAlt'),'')=json_extract('{"v":"Illustrative sign inspection"}','$.v') THEN json_extract('{"v":"Black dimensional ATELIER logo and lettering on a pale stone wall"}','$.v') ELSE json_extract(draft_json,'$.imageAlt') END,'$.imageKind',CASE WHEN coalesce(json_extract(draft_json,'$.imageKind'),'')=json_extract('{"v":"concept"}','$.v') THEN json_extract('{"v":"concept"}','$.v') ELSE json_extract(draft_json,'$.imageKind') END),published_json=json_set(published_json,'$.title',CASE WHEN coalesce(json_extract(published_json,'$.title'),'')=json_extract('{"v":"How Your Custom Sign Project Works"}','$.v') THEN json_extract('{"v":"Your Idea. Made into a Sign."}','$.v') ELSE json_extract(published_json,'$.title') END,'$.intro',CASE WHEN coalesce(json_extract(published_json,'$.intro'),'')=json_extract('{"v":"Start with what you know. We’ll clarify the remaining details with you before confirming a quote and production specification."}','$.v') THEN json_extract('{"v":"A clear path from your first reference to an agreed specification, production and delivery. Start with the details you have."}','$.v') ELSE json_extract(published_json,'$.intro') END,'$.body',json_extract('{"v":"## Share Your Brief\n\nA logo, a reference or a photo of the space is enough to begin the discussion.\n\nWe review the starting information and clarify the style, size, quantity and any open requirements with you.\n\nA saved enquiry and a clear starting point for your project.\n\n## Specification & Quote\n\nBring the artwork, construction and supplied scope together before the order moves forward.\n\nWe review the artwork, materials, lighting, fixing and delivery requirements, then prepare a project-based quote.\n\nReview the specification, price, inclusions and order terms. Approve the agreed requirements in writing before production.\n\n## Production & Checks\n\nThe approved details guide fabrication, finishing and the checks required for your sign.\n\nWe make your sign to the confirmed requirements and carry out the agreed appearance, construction and lighting checks where applicable.\n\nComplete the agreed order checks and confirm the packing and dispatch arrangements.\n\n## Delivery Preparation\n\nPlan the packing, shipment and local installation together, before dispatch.\n\nWe prepare the agreed protection and shipment arrangements, and confirm the supplied installation information.\n\nKnow the shipping scope, timing and import responsibilities. Resolve local fixing, electrical work and approvals with your installer."}','$.v'),'$.image',CASE WHEN coalesce(json_extract(published_json,'$.image'),'')=json_extract('{"v":""}','$.v') THEN json_extract('{"v":"/assets/product-depth/metal-cut.webp"}','$.v') ELSE json_extract(published_json,'$.image') END,'$.imageAlt',CASE WHEN coalesce(json_extract(published_json,'$.imageAlt'),'')=json_extract('{"v":"Illustrative sign inspection"}','$.v') THEN json_extract('{"v":"Black dimensional ATELIER logo and lettering on a pale stone wall"}','$.v') ELSE json_extract(published_json,'$.imageAlt') END,'$.imageKind',CASE WHEN coalesce(json_extract(published_json,'$.imageKind'),'')=json_extract('{"v":"concept"}','$.v') THEN json_extract('{"v":"concept"}','$.v') ELSE json_extract(published_json,'$.imageKind') END),version=version+1 WHERE type='page' AND slug='how-it-works' AND status='published' AND replace(json_extract(draft_json,'$.body'),char(13),'')=json_extract('{"v":"## 1. Share the Starting Point\n\nTell us the use, delivery country and preferred sign style. A logo, reference photo or initial idea is enough to begin. If dimensions, material or timing are undecided, say so rather than guessing a production specification.\n\n## 2. Review the Design and Location\n\nContinue the discussion with artwork, approximate dimensions, quantities and photos of the intended mounting area. We clarify the face, finish, depth, lighting and fixing direction, together with destination-specific requirements that need review.\n\n## 3. Check the Project Quote\n\nRead the proposed specifications, currency, included components, delivery scope, costs and exclusions. If information is provisional, ask which assumptions the quote uses and what could change when the details are confirmed. An enquiry or preliminary quote is not production approval.\n\n## 4. Confirm the Order and Production Requirements\n\nConfirm artwork, spelling, dimensions, finishes, lighting, quantities and approval responsibilities in writing. The quotation and order documents establish the seller, payment arrangements, applicable terms and the point at which fabrication is authorised.\n\n## 5. Fabrication, Checks and Packing\n\nThe production partner works to the approved requirements. Agree in advance which appearance checks, lighting checks, inspection records, packing arrangements and dispatch information are needed. Supplier photographs are references, not proof that a particular order has passed inspection.\n\n## 6. Shipping and Installation Preparation\n\nConfirm the destination, shipping scope, production and transit timing, import responsibilities and the information required by the local installer. Identify any fixing, electrical connection, access or approval work outside the supplied scope before dispatch.\n\n## Useful to Have, but Not Required to Start\n\n- Your logo, text or reference image.\n- Approximate dimensions and quantity.\n- A photo of the intended location and mounting surface.\n- Indoor or outdoor use.\n- Delivery country and city.\n- Preferred timing and any opening or installation deadline.\n\n## Questions About the Process\n\n### When is the price confirmed?\n\nAfter the project information and scope have been reviewed. Confirm any assumptions, exclusions and validity conditions in the quotation before agreeing the order.\n\n### Can I change the design after approval?\n\nContact your project representative promptly. Whether a change is possible, and any cost or timing impact, depends on the actual stage and agreed order terms. Do not assume a requested change has been accepted until confirmed.\n\n### What if something arrives damaged or appears incorrect?\n\nKeep the packaging, photograph the issue and contact the agreed project contact promptly with the order reference. The relevant order documents and support arrangements determine the next steps."}','$.v') AND replace(json_extract(published_json,'$.body'),char(13),'')=json_extract('{"v":"## 1. Share the Starting Point\n\nTell us the use, delivery country and preferred sign style. A logo, reference photo or initial idea is enough to begin. If dimensions, material or timing are undecided, say so rather than guessing a production specification.\n\n## 2. Review the Design and Location\n\nContinue the discussion with artwork, approximate dimensions, quantities and photos of the intended mounting area. We clarify the face, finish, depth, lighting and fixing direction, together with destination-specific requirements that need review.\n\n## 3. Check the Project Quote\n\nRead the proposed specifications, currency, included components, delivery scope, costs and exclusions. If information is provisional, ask which assumptions the quote uses and what could change when the details are confirmed. An enquiry or preliminary quote is not production approval.\n\n## 4. Confirm the Order and Production Requirements\n\nConfirm artwork, spelling, dimensions, finishes, lighting, quantities and approval responsibilities in writing. The quotation and order documents establish the seller, payment arrangements, applicable terms and the point at which fabrication is authorised.\n\n## 5. Fabrication, Checks and Packing\n\nThe production partner works to the approved requirements. Agree in advance which appearance checks, lighting checks, inspection records, packing arrangements and dispatch information are needed. Supplier photographs are references, not proof that a particular order has passed inspection.\n\n## 6. Shipping and Installation Preparation\n\nConfirm the destination, shipping scope, production and transit timing, import responsibilities and the information required by the local installer. Identify any fixing, electrical connection, access or approval work outside the supplied scope before dispatch.\n\n## Useful to Have, but Not Required to Start\n\n- Your logo, text or reference image.\n- Approximate dimensions and quantity.\n- A photo of the intended location and mounting surface.\n- Indoor or outdoor use.\n- Delivery country and city.\n- Preferred timing and any opening or installation deadline.\n\n## Questions About the Process\n\n### When is the price confirmed?\n\nAfter the project information and scope have been reviewed. Confirm any assumptions, exclusions and validity conditions in the quotation before agreeing the order.\n\n### Can I change the design after approval?\n\nContact your project representative promptly. Whether a change is possible, and any cost or timing impact, depends on the actual stage and agreed order terms. Do not assume a requested change has been accepted until confirmed.\n\n### What if something arrives damaged or appears incorrect?\n\nKeep the packaging, photograph the issue and contact the agreed project contact promptly with the order reference. The relevant order documents and support arrangements determine the next steps."}','$.v');
